    (3, 3163, 'HUESO DESMINERALIZADO EN PASTA OPTECURE 10 CC 650-00-10', 0, 9, 'ACTIVO', 'A', 1, 1, 'S', null, null, null, null, 1, 1, 1, null, null, null, null, null, null, null, null, null, false, null, false, 2, 0, false, null, null, null, null, null),
    (3, 3164, 'HUESO DESMINERALIZADO EN PASTA OPTECURE 10CC ORTOGUA', 0, 9, 'ACTIVO', 'A', 1, 1, 'S', null, null, null, null, 1, 1, 1, null, null, null, null, null, null, null, null, null, false, null, false, 2, 0, false, null, null, null, null, null),
    (3, 3165, 'HUESO DESMINERALIZADO EN PASTA OPTECURE 5CC ORTOGUA', 0, 9, 'ACTIVO', 'A', 1, 1, 'S', null, null, null, null, 1, 1, 1, null, null, null, null, null, null, null, null, null, false, null, false, 2, 0, false, null, null, null, null, null),
    (3, 3166, 'HUESO DESMINERALIZADO JERINGA 1CC SURE FUCE PUTTY SP1', 0, 9, 'ACTIVO', 'A', 1, 1, 'S', null, null, null, null, 1, 1, 1, null, null, null, null, null, null, null, null, null, false, null, false, 2, 0, false, null, null, null, null, null),
    (3, 3167, 'HUESO DESMINERALIZADO JERINGA PUTTY 0.5 CC REPCA', 0, 9, 'ACTIVO', 'A', 1, 1, 'S', null, null, null, null, 1, 1, 1, null, null, null, null, null, null, null, null, null, false, null, false, 2, 0, false, null, null, null, null, null),
    (3, 3168, 'HUESO DESMINERALIZADO JERINGA PUTTY 1.0 CC 0315C1 REPCA', 0, 9, 'ACTIVO', 'A', 1, 1, 'S', null, null, null, null, 1, 1, 1, null, null, null, null, null, null, null, null, null, false, null, false, 2, 0, false, null, null, null, null, null),
    (3, 3169, 'HUESO DESMINERALIZADO PASTA OPTECURE + CCC 20CC OG *', 0, 9, 'ACTIVO', 'A', 1, 1, 'S', null, null, null, null, 1, 1, 1, null, null, null, null, null, null, null, null, null, false, null, false, 2, 0, false, null, null, null, null, null)) as x(loc, codigo, nombre, tipo, clasificacion, estado, estado_orig, minimo, maximo, adm_pm, estante, fila, bloque, proveedor, bodega,
      medida, presentacion, generico, descripcion, cod_prov, visual, codigo_producto, codigo_producto_ant, barras, barras_ant, correlativo, covid, clas_lab, revisado,
      tipo_art, costo, revi, usr_i, f_i, usr_m, f_m, prod_ant) loop
    if r.loc <> v_locn then
      select id into v_loc from public.localidades where organizacion_id = v_org and correlativo = r.loc; v_locn := r.loc;
    end if;
    if v_loc is null then continue; end if;
    v_cla := null; v_tp := null; v_tpcla := null; v_med := null; v_pre := null; v_prov := null; v_bod := null;
    select id into v_cla from public.clasificaciones_producto where localidad_id = v_loc and codigo_anterior = r.clasificacion;
    select id, clasificacion_id into v_tp, v_tpcla from public.tipos_producto where localidad_id = v_loc and codigo_anterior = r.tipo;
    if v_tp is null then
      if coalesce(r.tipo, 0) <> 0 then v_sintipo := v_sintipo + 1; end if;
    elsif v_cla is null or v_tpcla <> v_cla then
      v_tp := null; v_otra := v_otra + 1;   -- el tipo es de otra clasificación: el producto conserva la suya
    end if;
    select id into v_med from public.tipos_medida where localidad_id = v_loc and codigo_anterior = r.medida;
    select id into v_pre from public.presentaciones_producto where localidad_id = v_loc and codigo_anterior = r.presentacion;
    select id into v_bod from public.bodegas where localidad_id = v_loc and (codigo_anterior = r.bodega or (codigo_anterior is null and codigo = r.bodega)) order by (codigo_anterior = r.bodega) desc nulls last limit 1;
    select id into v_prov from public.proveedores where localidad_id = v_loc and codigo = r.proveedor;
    if v_prov is null and r.proveedor is not null then v_sinprov := v_sinprov + 1; end if;
    v_pm := upper(coalesce(r.adm_pm, '')) = 'S' and coalesce(r.maximo, 0) >= coalesce(r.minimo, 0);

    v_id := null;
    select id into v_id from public.productos where localidad_id = v_loc and codigo_anterior = r.codigo;
    -- Código de producto y de barras únicos en la empresa: si ya los tiene otro producto, quedan solo en la columna «anterior».
    v_cp := r.codigo_producto; v_cb := r.barras;
    if v_cp is not null and exists (select 1 from public.productos where localidad_id = v_loc and upper(codigo_producto) = upper(v_cp) and id is distinct from v_id) then v_cp := null; end if;
    if v_cb is not null and exists (select 1 from public.productos where localidad_id = v_loc and codigo_barras = v_cb and id is distinct from v_id) then v_cb := null; end if;
    if v_id is null then
      if exists (select 1 from public.productos where localidad_id = v_loc and codigo = r.codigo) then
        raise exception 'El código % de la 2-0% lo tiene otro producto: ejecuta primero la parte 1 del script 195.', r.codigo, r.loc;
      end if;
      insert into public.productos (organizacion_id, localidad_id, codigo, nombre, codigo_producto, clasificacion_id, tipo_producto_id, estado, proveedor_id,
        codigo_barras, presentacion_id, tipo_medida_id, generico, punto_minimo, minimo, maximo, precio_costo, estante, fila, bloque, bodega_id, descripcion,
        codigo_anterior, clasificacion_anterior, tipo_producto_anterior, tipo_medida_anterior, presentacion_anterior, bodega_codigo_anterior, proveedor_codigo_anterior,
        estado_original, tipo_articulo_anterior, revi_exis_inv, producto_ant, codigo_producto_anterior, usuario_ingresa_anterior, fecha_ingresa_anterior,
        usuario_modifica_anterior, fecha_modifica_anterior, origen_anterior, codigo_proveedor_anterior, codigo_visual, administracion_pm, correlativo_bodega,
        covid, clasificacion_lab, revisado, generico_anterior, codigo_barras_anterior, minimo_anterior, maximo_anterior)
      values (v_org, v_loc, r.codigo, r.nombre, v_cp, v_cla, v_tp, r.estado, v_prov,
        v_cb, v_pre, v_med, r.generico is not null, v_pm, coalesce(r.minimo, 0), coalesce(r.maximo, 0), r.costo, r.estante, r.fila, r.bloque, v_bod, r.descripcion,
        r.codigo, r.clasificacion, r.tipo, r.medida, r.presentacion, r.bodega, r.proveedor,
        r.estado_orig, r.tipo_art, r.revi, r.prod_ant, r.codigo_producto_ant, r.usr_i, r.f_i::date,
        r.usr_m, r.f_m::date, 'MIGRADO', r.cod_prov, r.visual, r.adm_pm, r.correlativo,
        r.covid, r.clas_lab, r.revisado, r.generico, r.barras_ant, r.minimo, r.maximo);
      v_n := v_n + 1;
    else
      update public.productos set nombre = r.nombre, codigo_producto = v_cp, clasificacion_id = v_cla, tipo_producto_id = v_tp, estado = r.estado,
        proveedor_id = coalesce(v_prov, proveedor_id), codigo_barras = v_cb, presentacion_id = v_pre, tipo_medida_id = v_med, generico = r.generico is not null,
        punto_minimo = v_pm, minimo = coalesce(r.minimo, 0), maximo = coalesce(r.maximo, 0), precio_costo = r.costo, estante = r.estante, fila = r.fila,
        bloque = r.bloque, bodega_id = v_bod, descripcion = r.descripcion,
        clasificacion_anterior = r.clasificacion, tipo_producto_anterior = r.tipo, tipo_medida_anterior = r.medida, presentacion_anterior = r.presentacion,
        bodega_codigo_anterior = r.bodega, proveedor_codigo_anterior = r.proveedor, estado_original = r.estado_orig, tipo_articulo_anterior = r.tipo_art,
        revi_exis_inv = r.revi, producto_ant = r.prod_ant, codigo_producto_anterior = r.codigo_producto_ant, usuario_ingresa_anterior = r.usr_i,
        fecha_ingresa_anterior = r.f_i::date, usuario_modifica_anterior = r.usr_m, fecha_modifica_anterior = r.f_m::date, origen_anterior = 'MIGRADO',
        codigo_proveedor_anterior = r.cod_prov, codigo_visual = r.visual, administracion_pm = r.adm_pm, correlativo_bodega = r.correlativo, covid = r.covid,
        clasificacion_lab = r.clas_lab, revisado = r.revisado, generico_anterior = r.generico, codigo_barras_anterior = r.barras_ant,
        minimo_anterior = r.minimo, maximo_anterior = r.maximo
      where id = v_id;
      v_a := v_a + 1;
    end if;
  end loop;
  raise notice '%', format('Parte 12 de 13: %s productos nuevos, %s actualizados. Sin tipo de producto: %s; con tipo de otra clasificación (se deja sin tipo): %s; con proveedor aún no migrado: %s.',
    v_n, v_a, v_sintipo, v_otra, v_sinprov);
end;
$migra$;

notify pgrst, 'reload schema';
